# ------------------------------------------------------------------------- snake sim
DIRS = [(0, -1), (1, 0), (0, 1), (-1, 0)]  # up, right, down, left (y grows downward)
LEFT, RIGHT, STRAIGHT = 0, 1, 2


class SnakeSim:
    def __init__(self, seed: int) -> None:
        self.rng = np.random.default_rng(seed)
        self.body = [(5, 5), (4, 5), (3, 5)]
        self.heading = 1
        self.food = self.place_food()
        self.hunger = 0
        self.eaten = 0
        self.total = 0.0

    def place_food(self) -> tuple[int, int]:
        free = [(x, y) for y in range(10) for x in range(10) if (x, y) not in self.body]
        return free[int(self.rng.integers(len(free)))]

    def turned(self, action: int) -> int:
        return {LEFT: (self.heading - 1) % 4, RIGHT: (self.heading + 1) % 4, STRAIGHT: self.heading}[action]

    def fatal(self, heading: int) -> bool:
        (hx, hy), (dx, dy) = self.body[0], DIRS[heading]
        nx, ny = hx + dx, hy + dy
        return not (0 <= nx < 10 and 0 <= ny < 10) or (nx, ny) in self.body[:-1]

    def obs(self) -> list[float]:
        (hx, hy), (fx, fy) = self.body[0], self.food
        danger = [float(self.fatal(self.turned(a))) for a in (STRAIGHT, LEFT, RIGHT)]
        heading = [float(i == self.heading) for i in range(4)]
        food = [float(v) for v in (fy < hy, fx > hx, fy > hy, fx < hx)]
        return danger + heading + food + [float(len(self.body))]

    def rule(self) -> int:
        (hx, hy), (fx, fy) = self.body[0], self.food
        dx, dy = fx - hx, fy - hy
        axes = sorted([(abs(dx), "x"), (abs(dy), "y")])
        axis = next((a for d, a in axes if d), None)
        want = {("x", True): 1, ("x", False): 3, ("y", True): 2, ("y", False): 0}
        desired = want[(axis, (dx if axis == "x" else dy) > 0)] if axis else self.heading
        action = {self.heading: STRAIGHT, (self.heading - 1) % 4: LEFT, (self.heading + 1) % 4: RIGHT}.get(desired)
        if action is None or self.fatal(self.turned(action)):
            safe = [a for a in (STRAIGHT, LEFT, RIGHT) if not self.fatal(self.turned(a))]
            action = safe[0] if safe else STRAIGHT
        return action

    def step(self, action: int) -> tuple[float, bool]:
        self.heading = self.turned(action)
        if self.fatal(self.heading):
            self.total -= 1.0
            return -1.0, True
        (hx, hy), (dx, dy) = self.body[0], DIRS[self.heading]
        self.body.insert(0, (hx + dx, hy + dy))
        if self.body[0] == self.food:
            self.eaten += 1
            self.hunger = 0
            self.food = self.place_food()
            self.total += 1.0
            return 1.0, False
        self.body.pop()
        self.hunger += 1
        return 0.0, self.hunger >= 100

    def draw(self) -> core.DrawState:
        cells = [
            core.Drawable("head" if i == 0 else "body", float(x), float(y), 1.0, "snake", 0 if i == 0 else None)
            for i, (x, y) in enumerate(self.body)
        ]
        food = core.Drawable("food", float(self.food[0]), float(self.food[1]), 1.0, None, None)
        return core.DrawState(10.0, 10.0, (*cells, food))


def snake_spec(max_steps: int = 1000) -> core.WorldSpec:
    return core.WorldSpec(
        world="snake",
        variant="default",
        agents=("snake-0",),
        teams=(core.TeamSpec("snake", (0,), "food", "higher"),),
        obs_len=12,
        action=core.Discrete(3),
        max_steps=max_steps,
        measures=(),
        sight=None,
    )


def play_snake(seed: int, max_steps: int, policy: Any = None) -> dict[str, Any]:
    sim = SnakeSim(seed)
    f32 = np.float32
    reset = core.Step(np.array([sim.obs()], f32), np.zeros(1, f32), np.ones(1, bool), False, False)
    steps, draws, frames = [], [sim.draw()], [core.Frame(0, sim.draw(), {"snake": 0.0}, np.zeros(1, f32))]
    obs_seen, actions = [sim.obs()], []
    for t in range(1, max_steps + 1):
        action = sim.rule() if policy is None else policy(sim)
        reward, died = sim.step(action)
        truncated = not died and t == max_steps
        step = core.Step(
            np.array([sim.obs()], f32),
            np.array([reward], f32),
            np.ones(1, bool),
            died or truncated,
            truncated,
        )
        steps.append({"actions": [action], "step": step})
        actions.append(action)
        draws.append(sim.draw())
        frames.append(core.Frame(t, sim.draw(), {"snake": float(sim.eaten)}, np.array([reward], f32)))
        if step.done:
            break
        obs_seen.append(sim.obs())
    result = core.EpisodeResult(seed, len(steps), {"snake": float(sim.eaten)}, {"snake": sim.total}, {})
    return {
        "reset": reset,
        "steps": steps,
        "draws": draws,
        "frames": frames,
        "result": result,
        "obs": obs_seen,
        "actions": actions,
        "hit_step_limit": steps[-1]["step"].truncated,
    }


