def run_recording() -> dict[str, Any]:
    rng = np.random.default_rng(2026)
    config, spec = run_config(), snake_spec()
    record = runlog.RunRecord(
        config, spec, datetime(2026, 10, 17, 10, 0, 0), datetime(2026, 10, 17, 10, 4, 12), "finished", None, RUN_PATH
    )
    lengths = [140, 95, 210, 180, 160, 230, 200, 260, 240, 285]
    episodes = [
        core.EpisodeResult(int(rng.integers(0, 1_000_000)), n, {"snake": float(i // 2)}, {"snake": float(i // 2) - 1.0}, {})
        for i, n in enumerate(lengths)
