    write("core.Step/samples/prey_one_caught.json", encode(core.Step(obs, rewards, active, False, False)))
    snake_12 = core.EpisodeResult(1_000_003, 412, {"snake": 12.0}, {"snake": 11.0}, {})
    write("core.EpisodeResult/samples/snake_12_food.json", encode(snake_12))
    both = core.EpisodeResult(
        1_000_011, 1000, {"prey": 31.0, "predator": 4.0}, {"prey": 27.0, "predator": 4.0}, {"prey_left": 2.0}
    )
    write("core.EpisodeResult/samples/prey_both_teams.json", encode(both))
    write("core.Episode/samples/snake_untraced.json", encode(core.Episode(snake_12, None, False)))
    tank = tuple(
        core.Drawable("fish", x, y, 0.5, "fish", i)
        for i, (x, y) in enumerate(np.round(rng.uniform(1, 19, (8, 2)), 2).tolist())
    )
    ball = core.Drawable("ball", 10.0, 7.5, 1.0, None, None)
