def write_component_samples() -> None:
    rng = np.random.default_rng(8)
    snake_means = baselines.BaselineMeans("snake", "default", {"snake": 0.15}, {"snake": 9.6})
    write("baselines.BaselineMeans/samples/snake.json", encode(snake_means))
    prey_means = baselines.BaselineMeans(
