"""Replay double of `core.World`: a recorded episode, served step by step.

`make()` is the rule snake from seed 42 with a 5-step limit (a `max_steps` override), so the
episode ends truncated at step 5. `reset` accepts only the recorded seed and `step` only the
recorded actions; anything else fails loudly instead of inventing a state.
"""

from __future__ import annotations

from typing import Any

import numpy as np
from contracts_load import decode, read

from rllab.core import ActionError, Array, Discrete, DrawState, EpisodeResult, Step, WorldSpec


class ReplayWorld:
    def __init__(self, data: dict[str, Any]) -> None:
        self.spec: WorldSpec = decode(data["spec"], WorldSpec)
        self.seed: int = data["seed"]
        self._reset: Step = decode(data["reset"], Step)
        self._steps = [(np.asarray(s["actions"]), decode(s["step"], Step)) for s in data["steps"]]
        self._result: EpisodeResult = decode(data["result"], EpisodeResult)
        self._draws = [decode(d, DrawState) for d in data["draws"]]
        self._t: int | None = None

    @property
    def recorded_actions(self) -> list[Array]:
        return [actions for actions, _ in self._steps]

    def reset(self, seed: int) -> Step:
        if seed != self.seed:
            raise ValueError(f"the double was recorded from seed {self.seed}, not {seed}")
        self._t = 0
        return self._reset

    def step(self, actions: Array) -> Step:
        if self._t is None:
            raise RuntimeError("step before reset")
        if self._t == len(self._steps):
            raise RuntimeError("step after the episode is done")
        actions = np.asarray(actions)
        self._check_space(actions)
        expected, step = self._steps[self._t]
        if actions.shape != expected.shape or not np.allclose(actions, expected):
            raise AssertionError(
                f"step {self._t + 1}: actions {actions.tolist()} differ from the recorded "
                f"{expected.tolist()}"
            )
        self._t += 1
        return step

    def result(self) -> EpisodeResult:
        if self._t != len(self._steps):
            raise RuntimeError("the recorded episode is not finished")
        return self._result

    def draw(self) -> DrawState:
        if self._t is None:
            raise RuntimeError("draw before reset")
        return self._draws[self._t]

    def _check_space(self, actions: Array) -> None:
        space = self.spec.action
        for agent, value in zip(self.spec.agents, actions, strict=True):
            if isinstance(space, Discrete):
                inside = value.shape == () and float(value).is_integer() and 0 <= value < space.n
            else:
                inside = value.shape == (space.dims,) and bool(
                    np.all((space.low <= value) & (value <= space.high))
                )
            if not inside:
                raise ActionError(agent, value.tolist())


def make() -> ReplayWorld:
    return ReplayWorld(read("core.World", "recording.json"))

