"""Replay double of `core.Policy`: recorded observations and the actions taken on them.

`make()` is the snake rule over the 5 observations of the `core.World` double (seed 42), so the
two together replay that episode. An observation outside the recording raises `KeyError`.
"""

from __future__ import annotations

from typing import Any

import numpy as np
from contracts_load import read

from rllab.core import Array


class ReplayPolicy:
    def __init__(self, calls: list[dict[str, Any]]) -> None:
        self.calls = [
            (np.asarray(c["obs"], np.float32), np.asarray(c["actions"])) for c in calls
        ]

    def act(self, obs: Array, rng: np.random.Generator) -> Array:
        obs = np.asarray(obs)
        for seen, actions in self.calls:
            if seen.shape == obs.shape and np.allclose(seen, obs):
                return actions.copy()
        raise KeyError(f"observation not in the recording: {obs.tolist()}")


def make() -> ReplayPolicy:
    return ReplayPolicy(read("core.Policy", "recording.json")["calls"])

