"""Replay doubles of `baselines.RandomPolicy`: recorded uniform draws, served in order.

`make("snake")`: 5 draws from `Discrete(3)`. `make("fish")`: 5 pushes from `Box(2, -1, 1)`.
Each `act` returns the next draw for one agent, whatever the observation; a sixth call fails.
"""

from __future__ import annotations

import numpy as np
from contracts_load import decode, read

from rllab.core import ActionSpace, Array


class ReplayRandom:
    def __init__(self, name: str) -> None:
        data = read("baselines.RandomPolicy", f"{name}.json")
        self.action: ActionSpace = decode(data["action"], ActionSpace)
        self.draws = [np.asarray(a) for a in data["actions"]]
        self._next = 0

    def act(self, obs: Array, rng: np.random.Generator) -> Array:
        if self._next == len(self.draws):
            raise IndexError(f"only {len(self.draws)} draws were recorded")
        self._next += 1
        return self.draws[self._next - 1].copy()


def make(name: str) -> ReplayRandom:
    return ReplayRandom(name)

