50% and 100% checkpoints. `make(name=..., status=...)` renames the run (its config, path and
checkpoints) and changes its status, so one recording stands for the runs of a batch.
"""

from __future__ import annotations

import dataclasses

from contracts_load import decode, read

from rllab.core import EpisodeResult
from rllab.runlog import Checkpoint, EvalPoint, RunRecord


class ReplayRun:
    def __init__(
        self,
        record: RunRecord,
        episodes: list[EpisodeResult],
        evals: list[EvalPoint],
        checkpoints: list[Checkpoint],
    ) -> None:
        self.record = record
        self._episodes = episodes
        self._evals = evals
        self._checkpoints = checkpoints

    def episodes(self) -> list[EpisodeResult]:
        return list(self._episodes)

    def evals(self) -> list[EvalPoint]:
        return list(self._evals)

    def checkpoints(self) -> list[Checkpoint]:
        return list(self._checkpoints)


def make(name: str | None = None, status: str | None = None) -> ReplayRun:
    data = read("runlog.Run", "recording.json")
    record: RunRecord = decode(data["record"], RunRecord)
    checkpoints = [decode(c, Checkpoint) for c in data["checkpoints"]]
    if name is not None:
        path = record.path.parent / name
        config = dataclasses.replace(record.config, name=name)
        record = dataclasses.replace(record, config=config, path=path)
        checkpoints = [
            dataclasses.replace(c, run=name, path=path / "checkpoints" / c.path.name)
            for c in checkpoints
        ]
    if status is not None:
