        record = dataclasses.replace(record, status=status, ended=ended)
    return ReplayRun(
        record,
        [decode(e, EpisodeResult) for e in data["episodes"]],
        [decode(p, EvalPoint) for p in data["evals"]],
        checkpoints,
    )

