"""Replay double of `runlog.RunWriter`: the writes of the `runlog.Run` double's run, in order.

Built with the contract constructor; it checks the config and spec against the recording and
each later call against the next recorded call, returning the recorded `Checkpoint` and
`RunRecord`. `remaining()` counts the recorded calls not yet made.
"""

from __future__ import annotations

from collections.abc import Mapping
from pathlib import Path
from typing import Any

from contracts_load import decode, encode, read

from rllab.core import EpisodeResult, RunConfig, WorldSpec
from rllab.runlog import Checkpoint, EvalPoint, Failure, RunRecord


class ReplayRunWriter:
    def __init__(self, root: Path, config: RunConfig, spec: WorldSpec) -> None:
        data = read("runlog.RunWriter", "recording.json")
        if config != decode(data["config"], RunConfig):
            raise AssertionError(f"config {config.name} differs from the recorded one")
        if spec != decode(data["spec"], WorldSpec):
            raise AssertionError("spec differs from the recorded one")
        self.root = root
        self._calls: list[dict[str, Any]] = data["calls"]
        self._next = 0

    def remaining(self) -> int:
        return len(self._calls) - self._next

    def _call(self, method: str, args: dict[str, Any]) -> Any:
        if not self.remaining():
            raise AssertionError(f"{method}: every recorded call was made")
        call = self._calls[self._next]
        if call["method"] != method or encode(args) != call["args"]:
            raise AssertionError(
                f"call {self._next}: {method}({encode(args)}) differs from the recorded "
                f"{call['method']}({call['args']})"
            )
        self._next += 1
        return call.get("returns")

    def episode(self, result: EpisodeResult) -> None:
        self._call("episode", {"result": result})

    def eval(self, point: EvalPoint) -> None:
        self._call("eval", {"point": point})

    def checkpoint(self, pct: int, step: int, state: Mapping[str, dict[str, object]]) -> Checkpoint:
        returned = self._call("checkpoint", {"pct": pct, "step": step, "state": state})
        return decode(returned, Checkpoint)

    def close(self, status: str, failure: Failure | None = None) -> RunRecord:
        returned = self._call("close", {"status": status, "failure": failure})
        return decode(returned, RunRecord)

